"""Persistent acoustic anchors generated by Voice Design, never uploaded audio."""
from dataclasses import dataclass
from array import array
import hashlib
import json
import logging
from pathlib import Path
import tempfile
import sys
import wave
from voice_design import without_tags

log = logging.getLogger(__name__)
CACHE_VERSION = 'ming-c88c023-voice-reference-v2'


@dataclass(frozen=True)
class VoiceReference:
    path: Path
    text: str


class VoiceReferences:
    def __init__(self, directory: Path, model_revision: str):
        self.directory = directory
        self.model_revision = model_revision

    def key(self, segment) -> str:
        identity = [CACHE_VERSION, self.model_revision, segment.speaker,
                    segment.identity, segment.style, segment.seed, segment.language_id]
        return hashlib.sha256(json.dumps(identity, ensure_ascii=False).encode()).hexdigest()

    def get(self, segment) -> VoiceReference | None:
        directory = self.directory / self.key(segment)
        try:
            metadata = json.loads((directory / 'reference.json').read_text())
            path = directory / 'reference.wav'
            with wave.open(str(path), 'rb') as audio:
                valid = (audio.getnchannels() == 1 and audio.getsampwidth() == 2
                         and 1 <= audio.getnframes() / audio.getframerate() <= 15)
            if (not valid or not metadata['text'].strip()
                    or metadata['sha256'] != hashlib.sha256(path.read_bytes()).hexdigest()):
                raise ValueError('Invalid reference audio or transcript')
            return VoiceReference(path, metadata['text'])
        except FileNotFoundError:
            return None
        except (ValueError, KeyError, OSError, EOFError, wave.Error):
            log.warning('Ignoring invalid voice reference %s', directory.name)
            return None

    def save(self, segment, pcm: bytes, sample_rate: int) -> None:
        # Tiny utterances and unusually long outputs are poor cloning anchors.
        # Never crop audio independently of its transcript.
        duration = len(pcm) / (2 * sample_rate)
        if not 1 <= duration <= 15 or not pcm:
            return
        samples = array('h')
        samples.frombytes(pcm)
        if sys.byteorder != 'little':
            samples.byteswap()
        # Do not pin silence/failed outputs as a permanent character identity.
        if sum(abs(sample) >= 64 for sample in samples) < sample_rate * .2:
            return
        directory = self.directory / self.key(segment)
        try:
            directory.mkdir(mode=0o700, parents=True, exist_ok=True)
            # Commit metadata last; checksum rejects interrupted/mismatched pairs.
            with tempfile.TemporaryDirectory(dir=directory) as staging:
                audio_path = Path(staging) / 'reference.wav'
                with wave.open(str(audio_path), 'wb') as audio:
                    audio.setnchannels(1)
                    audio.setsampwidth(2)
                    audio.setframerate(sample_rate)
                    audio.writeframes(pcm)
                metadata_path = Path(staging) / 'reference.json'
                metadata_path.write_text(json.dumps({
                    'text': segment.text,
                    'sha256': hashlib.sha256(audio_path.read_bytes()).hexdigest(),
                }, ensure_ascii=False))
                audio_path.replace(directory / 'reference.wav')
                metadata_path.replace(directory / 'reference.json')
        except OSError:
            # Cache persistence must not discard successfully generated speech.
            log.exception('Could not persist voice reference %s', directory.name)

    def options(self, segment) -> tuple[dict, bool]:
        prompt = segment.prompt()
        reference = self.get(segment)
        if reference:
            return {
                'task': 'TTS' if prompt.language_id in {'en', 'zh'} else 'MULTILINGUAL',
                'text': prompt.text, 'language_id': prompt.language_id,
                'prompt_wav_path': str(reference.path), 'prompt_text': reference.text,
                'use_spk_emb': True, 'raw_text': True,
            }, False
        return {
            'task': 'VOICE_DESIGN', 'text': without_tags(prompt.text), 'language_id': prompt.language_id,
            'controls': {'style': prompt.instruction}, 'use_zero_spk_emb': True, 'raw_text': True,
        }, True
